import java.math.BigDecimal;
import java.text.SimpleDateFormat;

public class TransferFundsResponseMapper {

    public String format(TransferFundsResponseBusiness business) throws Exception {
        if (business == null) {
            throw new IllegalArgumentException("Business response cannot be null");
        }
        TransferFundsResponseXml xml = new TransferFundsResponseXml();
        xml.transferId = business.getTransferId();
        xml.transferStatus = business.getTransferStatus();

        if (business.getExecutionDate() != null) {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMdd");
            xml.executionDate = sdf.format(business.getExecutionDate());
        }

        if (business.getExecutionTime() != null) {
            SimpleDateFormat timeSdf = new SimpleDateFormat("HH:mm:ss");
            xml.executionTime = timeSdf.format(business.getExecutionTime());
        } else {
            xml.executionTime = "00:00:00";
        }

        if (business.getAmount() != null) {
            xml.amount = business.getAmount().setScale(2).toPlainString();
        }

        xml.currency = business.getCurrency();

        String srcAcc = business.getSourceAccount() != null ? business.getSourceAccount() : "";
        if (srcAcc.length() < 3) {
            srcAcc = " ".repeat(3 - srcAcc.length()) + srcAcc;
        }
        xml.sourceAccount = srcAcc;

        String tgtAcc = business.getTargetAccount() != null ? business.getTargetAccount() : "";
        if (tgtAcc.length() < 10) {
            tgtAcc = "0".repeat(10 - tgtAcc.length()) + tgtAcc;
        }
        xml.targetAccount = tgtAcc;

        if (business.getNewSourceBalance() != null) {
            xml.newSourceBalance = business.getNewSourceBalance().setScale(2).toPlainString();
        }

        if (business.getFraudCheckSkipped() != null) {
            xml.fraudCheckSkipped = business.getFraudCheckSkipped() ? "true" : "false";
        } else {
            xml.xsiNil = "true";
        }

        XmlMapper mapper = new XmlMapper();
        mapper.enable(SerializationFeature.INDENT_OUTPUT);
        mapper.configure(ToXmlGenerator.Feature.WRITE_XML_DECLARATION, false);
        return mapper.writeValueAsString(xml);
    }

    public TransferFundsResponseBusiness unformat(String xmlContent) throws Exception {
        XmlMapper mapper = new XmlMapper();
        TransferFundsResponseXml xml = mapper.readValue(xmlContent, TransferFundsResponseXml.xmlClass());
        TransferFundsResponseBusiness biz = new TransferFundsResponseBusiness();
        biz.setTransferId(xml.transferId);
        biz.setTransferStatus(xml.transferStatus);

        if (xml.executionDate != null && !xml.executionDate.isBlank()) {
            biz.setExecutionDate(new SimpleDateFormat("yyyyMMdd").parse(xml.executionDate));
        }

        if (xml.executionTime != null && !xml.executionTime.isBlank()) {
            try {
                biz.setExecutionTime(new SimpleDateFormat("HH:mm:ss").parse(xml.executionTime));
            } catch (Exception e) {
                biz.setExecutionTime(new java.util.Date(0L));
            }
        }

        if (xml.amount != null && !xml.amount.isBlank()) {
            biz.setAmount(new BigDecimal(xml.amount.replace(",", "")));
        }

        biz.setCurrency(xml.currency);

        String src = xml.sourceAccount;
        if (src != null) {
            src = src.replaceFirst("^+", "");
            while (src.startsWith(" ")) {
                src = src.substring(1);
            }
        }
        biz.setSourceAccount(src);

        String tgt = xml.targetAccount;
        if (tgt != null) {
            while (tgt.startsWith("0")) {
                tgt = tgt.substring(1);
            }
            if (tgt.isEmpty()) {
                tgt = "0";
            }
        }
        biz.setTargetAccount(tgt);

        if (xml.newSourceBalance != null && !xml.newSourceBalance.isBlank()) {
            biz.setNewSourceBalance(new BigDecimal(xml.newSourceBalance.replace(",", "")));
        }

        if ("true".equalsIgnoreCase(xml.xsiNil) || (xml.fraudCheckSkipped == null || xml.fraudCheckSkipped.isBlank())) {
            biz.setFraudCheckSkipped(null);
        } else {
            biz.setFraudCheckSkipped(Boolean.parseBoolean(xml.fraudCheckSkipped));
        }

        return biz;
    }
}

